let current=places[0],filter='all',pins=[],cart=[],auto=false,distance=3.55,dragging=false,moved=false,lastX=0,lastY=0,downX=0,downY=0,targetQuaternion=null,lastFocus=null;
try{pins=JSON.parse(localStorage.getItem('terra-pins')||'[]').filter(p=>places.some(x=>x.id===p.id)&&Number.isFinite(p.lat)&&Number.isFinite(p.lon));cart=JSON.parse(localStorage.getItem('terra-cart')||'[]').filter(c=>places.some(x=>x.id===c.place)&&Number.isInteger(c.index)&&c.index>=0&&c.index<3&&Number.isInteger(c.qty)&&c.qty>0)}catch{}
function persist(){try{localStorage.setItem('terra-pins',JSON.stringify(pins));localStorage.setItem('terra-cart',JSON.stringify(cart))}catch{}updateCounts()}
function updateCounts(){$('savedCount').textContent=pins.length;$('boxCount').textContent=cart.reduce((s,c)=>s+c.qty,0);$('savePlace').textContent=pins.some(p=>p.id===current.id)?'♥':'♡'}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),2800)}
function renderMeals(){const entries=current.meals.map((m,i)=>({m,i})).filter(({m})=>filter==='all'||filter==='veg'&&m.veg||filter==='protein'&&m.protein>=30);$('mealCount').textContent=entries.length+' meals';$('meals').innerHTML=entries.map(({m,i})=>`<article class="meal-card"><img src="assets/${m.image}" alt="${m.name} — illustrative food photography"><div><h4>${m.name}</h4><p>${m.description}</p><div class="meal-tags"><span>${m.veg?'Plant-based':'High protein'}</span><span>• ${m.protein}g protein*</span></div><div class="meal-bottom"><span class="price">$${m.price.toFixed(2)} <small>/ meal</small></span><button class="add-meal" data-add="${i}">+ Add</button></div></div></article>`).join('')||'<p class="empty">No meals match this filter. Try All meals.</p>';$('meals').querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.add),item=cart.find(c=>c.place===current.id&&c.index===i);if(item)item.qty++;else cart.push({place:current.id,index:i,qty:1});persist();toast(current.meals[i].name+' added to your box')})}
function select(place,focus=true,lat=place.lat,lon=place.lon){current=place;filter='all';$('placeName').textContent=place.name;$('tasteName').textContent=place.name;$('regionLabel').textContent=place.region;$('placeDescription').textContent=place.description;$('coordinate').textContent=`${Math.abs(lat).toFixed(2)}° ${lat>=0?'N':'S'} · ${Math.abs(lon).toFixed(2)}° ${lon>=0?'E':'W'}`;$('pinInfo').textContent=`⌖ Regional menu inspired by ${place.name}`;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter==='all'));document.querySelectorAll('[data-place]').forEach(b=>b.classList.toggle('active',b.dataset.place===place.id));renderMeals();updateCounts();if(focus&&earthGroup)targetQuaternion=new THREE.Quaternion().setFromUnitVectors(vector(lat,lon),new THREE.Vector3(0,0,1));updatePins();}
$('destinations').innerHTML=places.slice(0,6).map(p=>`<button data-place="${p.id}">${p.name} ↗</button>`).join('');document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>select(places.find(p=>p.id===b.dataset.place)));
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(t=>t.classList.toggle('selected',t===b));renderMeals()});
$('savePlace').onclick=()=>{if(pins.some(p=>p.id===current.id)){pins=pins.filter(p=>p.id!==current.id);toast('Destination removed')}else{pins.push({id:current.id,lat:current.lat,lon:current.lon});toast(current.name+' saved to your places')}persist();updatePins()};
function openDrawer(title){lastFocus=document.activeElement;$('drawerTitle').textContent=title;$('drawer').hidden=false;$('scrim').hidden=false;document.body.style.overflow='hidden';$('closeDrawer').focus()}
function closeDrawer(){$('drawer').hidden=true;$('scrim').hidden=true;document.body.style.overflow='';lastFocus?.focus()}
$('closeDrawer').onclick=closeDrawer;$('scrim').onclick=closeDrawer;document.addEventListener('keydown',e=>{if($('drawer').hidden)return;if(e.key==='Escape')closeDrawer();if(e.key==='Tab'){const a=[...$('drawer').querySelectorAll('button,input,select,a')].filter(el=>!el.disabled);if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0].focus()}}});
$('savedButton').onclick=()=>{openDrawer('Saved places');$('drawerContent').innerHTML=pins.length?pins.map((p,i)=>`<button class="saved-row" data-saved="${i}"><span>⌖ ${places.find(x=>x.id===p.id).name}</span><span>${p.lat.toFixed(1)}°, ${p.lon.toFixed(1)}° ↗</span></button>`).join(''):'<p class="empty">Your next adventure is waiting.<br>Click the globe to drop a pin,<br>or use the heart to save a destination.</p>';$('drawerContent').querySelectorAll('[data-saved]').forEach(b=>b.onclick=()=>{const p=pins[Number(b.dataset.saved)];select(places.find(x=>x.id===p.id),true,p.lat,p.lon);closeDrawer()})};
function renderCart(){const sum=cart.reduce((s,c)=>s+places.find(p=>p.id===c.place).meals[c.index].price*c.qty,0);$('drawerContent').innerHTML=cart.length?cart.map((c,i)=>{const p=places.find(p=>p.id===c.place),m=p.meals[c.index];return `<div class="cart-row"><div><strong>${m.name}</strong><small>${p.name} · $${m.price.toFixed(2)} each</small></div><div class="qty"><button data-qty="${i}" data-delta="-1" aria-label="Remove one ${m.name}">−</button><span>${c.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Add one ${m.name}">+</button></div></div>`}).join('')+`<div class="total"><span>Sample subtotal</span><strong>$${sum.toFixed(2)}</strong></div><p class="demo-note">Tax and delivery are not calculated. Nutrition estimates are illustrative, not verified.</p><label class="form-label" for="day">Preferred delivery day</label><select id="day"><option>Sunday</option><option>Monday</option><option>Wednesday</option></select><label class="form-label" for="notes">Meal preferences / allergy notes</label><input id="notes" placeholder="e.g. mild spice, no peanuts" maxlength="300"><p class="demo-note">A real kitchen must confirm allergen requirements before preparing food.</p><button class="primary" id="checkout">Preview my meal plan →</button>`:'<p class="empty">Your box is ready for an adventure.<br>Add a few meals from the globe to begin.</p><button class="primary" id="exploreMore">Explore the globe →</button>';$('drawerContent').querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const c=cart[Number(b.dataset.qty)];c.qty+=Number(b.dataset.delta);cart=cart.filter(c=>c.qty>0);persist();renderCart()});if($('exploreMore'))$('exploreMore').onclick=closeDrawer;if($('checkout'))$('checkout').onclick=()=>{const day=$('day').value,notes=$('notes').value;$('drawerContent').innerHTML=`<div class="success"><div style="font-size:40px">✦</div><h3>Your week, with a world of flavor.</h3><p>${cart.reduce((s,c)=>s+c.qty,0)} meals across ${new Set(cart.map(c=>c.place)).size} destinations.<br>Preferred delivery: ${day}<br>Sample subtotal: $${sum.toFixed(2)}</p><p id="confirmedNotes"></p><small>This is a demo meal plan. No order was submitted and no payment was taken. Your box stays saved on this device.</small><button class="primary" id="backToBox">Back to my box</button></div>`;$('confirmedNotes').textContent=notes?'Preferences: '+notes:'';$('backToBox').onclick=renderCart}}
$('boxButton').onclick=()=>{openDrawer('Your meal box');renderCart()};
// Real textured sphere; pins and surface clicks share the same geographic coordinate system.
function vector(lat,lon,r=1){const a=THREE.MathUtils.degToRad(lat),b=THREE.MathUtils.degToRad(lon);return new THREE.Vector3(Math.cos(a)*Math.cos(b)*r,Math.sin(a)*r,-Math.cos(a)*Math.sin(b)*r)}
